fn seeded(seed:u64)->sha3::Shake256Reader{let mut h=Shake256::default();h.update(b"phase-primitive-contract-v1");h.update(&seed.to_le_bytes());h.finalize_xof()}
fn zero(alg:&GlobalAnf,p:&GlobalPoly)->bool{p.0.iter().all(|(_,c)|alg.dag.find(*c)==0)}
fn main(){let args:Vec<_>=std::env::args().collect();let all=load_ops(&args[1]).unwrap();let start:usize=args[2].parse().unwrap();let(nq,nb,_,_)=analyze_ops(all.iter());use OperationType::*;assert_eq!(all[start].kind,Hmr);assert_eq!(all[start].c_condition.0,u64::MAX);let measured=all[start].q_target.0 as usize;assert_eq!(all[start+1].kind,PushCondition);let mut depth=1;let mut end=start+2;while depth>0{match all[end].kind{PushCondition=>depth+=1,PopCondition=>depth-=1,_=>{}}end+=1;}let ops=&all[start..end];let mut cursor=2;let mut u=Vec::new();while ops[cursor].kind==X{u.push(ops[cursor].q_target.0 as usize);cursor+=1;}let n=u.len();assert!(n>=2);let mut v=Vec::new();assert_eq!(ops[cursor].kind,CX);assert_eq!(ops[cursor].q_control1.0 as usize,u[0]);v.push(ops[cursor].q_target.0 as usize);cursor+=1;let borrow=if ops[cursor].kind==CX{assert_eq!(ops[cursor].q_control1.0 as usize,u[0]);let b=ops[cursor].q_target.0 as usize;cursor+=1;Some(b)}else{None};assert_eq!(ops[cursor].kind,CCX);cursor+=1;assert_eq!(ops[cursor].kind,CX);cursor+=1;for j in 1..n-1{assert_eq!(ops[cursor].kind,CX);assert_eq!(ops[cursor].q_control1.0 as usize,u[j]);v.push(ops[cursor].q_target.0 as usize);cursor+=4;}assert_eq!(ops[cursor].kind,CZ);assert_eq!(ops[cursor].q_control1.0 as usize,u[n-1]);v.push(ops[cursor].q_target.0 as usize);
let scratches:std::collections::BTreeSet<usize>=ops.iter().filter(|o|o.kind==CCX).map(|o|o.q_target.0 as usize).collect();assert_eq!(scratches.len(),n-1);let mut used=std::collections::BTreeSet::new();for o in ops{if matches!(o.kind,X|CX|CCX|Swap|R|Hmr|Z|CZ|CCZ){used.insert(o.q_target.0 as usize);}if matches!(o.kind,CX|CCX|Swap|CZ|CCZ){used.insert(o.q_control1.0 as usize);}if matches!(o.kind,CCX|CCZ){used.insert(o.q_control2.0 as usize);}}
let mut a=GlobalAnf::new(32);let mut q=vec![GlobalAnf::constant(0);nq as usize];let mut b=vec![GlobalAnf::constant(0);nb as usize];for wire in &used{if !scratches.contains(wire){let id=a.dag.variable(false);q[*wire]=GlobalAnf::constant(id);}}let mut cbits=std::collections::BTreeSet::new();for o in ops{for bit in [o.c_target.0,o.c_condition.0]{if bit!=u64::MAX{cbits.insert(bit as usize);}}}for bit in &cbits{let id=a.dag.variable(false);b[*bit]=GlobalAnf::constant(id);}let initial=q.clone();let mut carry=borrow.map_or(GlobalAnf::constant(0),|w|initial[w].clone());for j in 0..n-1{let nu=a.not(&initial[u[j]]);let x=a.xor(&carry,&nu);let y=a.xor(&initial[v[j]],&nu);let xy=a.and(&x,&y);carry=a.xor(&nu,&xy);}let nu=a.not(&initial[u[n-1]]);let x=a.and(&nu,&initial[v[n-1]]);let y=a.and(&nu,&carry);let z=a.and(&initial[v[n-1]],&carry);let xy=a.xor(&x,&y);carry=a.xor(&xy,&z);let target_difference=a.xor(&initial[measured],&carry);let mut first=None;let mut phase=GlobalAnf::constant(0);let mut base=GlobalAnf::constant(1);let mut stack=Vec::new();let mut mr=0;
for o in ops{if o.kind==PopCondition{base=stack.pop().unwrap();continue;}let c=if o.c_condition.0==u64::MAX{base.clone()}else{a.and(&base,&b[o.c_condition.0 as usize])};let t=o.q_target.0 as usize;let bt=o.c_target.0 as usize;match o.kind{CCX=>{let x=a.and(&q[o.q_control1.0 as usize],&q[o.q_control2.0 as usize]);let x=a.and(&x,&c);q[t]=a.xor(&q[t],&x);},CX=>{let x=a.and(&q[o.q_control1.0 as usize],&c);q[t]=a.xor(&q[t],&x);},X=>q[t]=a.xor(&q[t],&c),Z|CZ|CCZ|Neg=>{let mut x=c.clone();if o.kind!=Neg{x=a.and(&x,&q[t]);}if matches!(o.kind,CZ|CCZ){x=a.and(&x,&q[o.q_control1.0 as usize]);}if o.kind==CCZ{x=a.and(&x,&q[o.q_control2.0 as usize]);}phase=a.xor(&phase,&x);},R|Hmr=>{let random=a.fresh();if first.is_none(){first=Some(random.clone());}mr+=1;let x=a.and(&q[t],&random);let x=a.and(&x,&c);phase=a.xor(&phase,&x);let nc=a.not(&c);q[t]=a.and(&q[t],&nc);if o.kind==Hmr{let old=a.and(&b[bt],&nc);let new=a.and(&random,&c);b[bt]=a.xor(&old,&new);}},PushCondition=>{stack.push(base);base=c;},BitInvert=>b[bt]=a.xor(&b[bt],&c),BitStore0=>{let nc=a.not(&c);b[bt]=a.and(&b[bt],&nc);},BitStore1=>{let nc=a.not(&c);let old=a.and(&b[bt],&nc);b[bt]=a.xor(&old,&c);},_=>panic!("unsupported primitive opcode")}}
assert!(stack.is_empty());let expected=a.and(&first.unwrap(),&target_difference);let difference=a.xor(&phase,&expected);let proved_phase=zero(&a,&difference);let mut unresolved=Vec::new();for wire in &used{let want=if *wire==measured||scratches.contains(wire){GlobalAnf::constant(0)}else{initial[*wire].clone()};let d=a.xor(&q[*wire],&want);if !zero(&a,&d){unresolved.push(*wire);}}
let mut numeric_cases=0;for sample in 0..16{let mut init_rng=seeded(1000+sample);let mut iq=vec![0u64;nq as usize];for wire in &used{if !scratches.contains(wire){let mut raw=[0;8];XofReader::read(&mut init_rng,&mut raw);iq[*wire]=u64::from_le_bytes(raw);}}for seed in 0..4{let mut rng=seeded(seed);let mut peek=rng.clone();let mut raw=[0;8];XofReader::read(&mut peek,&mut raw);let m=u64::from_le_bytes(raw);let mut ci=borrow.map_or(0,|w|iq[w]);for j in 0..n{let x=!iq[u[j]];let y=iq[v[j]];ci=(x&y)^(x&ci)^(y&ci);}let expected=m&(iq[measured]^ci);let mut s=Simulator::new(nq as usize,nb as usize,&mut rng);s.qubits.copy_from_slice(&iq);s.phase=0x94d049bb133111eb;s.apply_iter(ops.iter());assert_eq!(s.phase^0x94d049bb133111eb,expected);for wire in &used{assert_eq!(s.qubits[*wire],if *wire==measured||scratches.contains(wire){0}else{iq[*wire]});}numeric_cases+=64;}}
println!("{}",serde_json::json!({"start":start,"end_exclusive":end,"ops":ops.len(),"n":n,"u":u,"v":v,"borrow":borrow,"measured":measured,"clean_scratch_preconditions":scratches,"all_other_used_entry_q_arbitrary":true,"all_used_entry_classical_bits_arbitrary":true,"all_internal_mr_universally_quantified":true,"phase_contract_proved":proved_phase,"q_contract_unresolved":unresolved,"phase_unresolved_terms":difference.0.len(),"outer_caps":a.capped,"input_nodes":a.dag.nodes.len(),"mr":mr,"protected_arbitrary_bitplane_cases":numeric_cases,"formula":"phase_delta = first_measurement * (entry_target XOR carryout(~entry_u + entry_v + entry_borrow))","not_a_repair":true}));}
